-- DATA_2026-09-05_social-groups-remaining-insert.sql
-- Muc dich: hoan tat migrate du lieu Social Groups tu Google Sheet
--   "social group url" (tab "FB Group") vao social_group_urls, phan
--   con thieu sau khi Claude da chay dang chung 800/1028 (sandbox) va
--   1000/1028 (public) truoc khi dung lai theo dung vai tro Architect/QA.
-- Da lam truoc do (KHONG can lam lai):
--   - ALTER TABLE them cot member_count (int) tren ca 2 schema.
--   - Da dang ky 12 tag moi vao social_group_tags (ca 2 schema): Mechanical,
--     Mechatronics, Industrial Automation, Industrial, IT, Dev, QA, BA, PM,
--     Network IT, Infrastructure IT, Devops (2 tag "Network (IT)" va
--     "Infrastructure (IT)" trong sheet goc DA duoc doi ten bo dau ngoac
--     vi charset constraint social_group_tags_name_charset_check khong
--     cho phep ky tu ( ) -- ĐÃ duoc User xac nhan dong y cach xu ly nay).
--   - Da XOA toan bo campaigns + social_group_urls cu (Cosmetic/Marketing/
--     Nontech/Nurse/Video Editor/Facebook Group va cac campaign gan voi
--     chung) tren ca 2 schema theo yeu cau User (thay database cu bang
--     database moi tu Google Sheet).
--   - Da insert 1000/1028 dong vao public.social_group_urls (con thieu
--     28 dong cuoi cung, sheet row 1001-1028).
--   - Da insert 800/1028 dong vao sandbox.social_group_urls (con thieu
--     228 dong cuoi cung, sheet row 801-1028).
-- Viec AG can lam: CHAY DUNG NGUYEN VAN file SQL nay 1 lan (qua Supabase
--   MCP hoac psql) de bo sung dung phan con thieu. KHONG chay lai toan
--   bo 1028 dong (se tao du lieu trung vi social_group_urls khong co
--   unique constraint tren cot url).
-- Sau khi chay xong, verify: public + sandbox deu phai co dung 1028
--   dong trong social_group_urls (xem query verify o cuoi file).
-- =====================================================================

-- PHAN 1: bo sung 28 dong con thieu cho PUBLIC (sheet row 1001-1028)
-- PHAN 2: bo sung 228 dong con thieu cho SANDBOX (sheet row 801-1028)
-- PHAN 3: VERIFY (bat buoc chay va doi chieu ket qua truoc khi bao PASS)
-- Ca 2 dong deu phai tra ve dung 1028.
select 'public.social_group_urls' as t, count(*) from public.social_group_urls
union all
select 'sandbox.social_group_urls', count(*) from sandbox.social_group_urls;

-- Khong dong nao duoc phep NULL member_count hoac rong group_type.
-- Ca 2 dong deu phai tra ve 0.
select count(*) from public.social_group_urls
  where member_count is null or group_type is null or array_length(group_type,1) is null;
select count(*) from sandbox.social_group_urls
  where member_count is null or group_type is null or array_length(group_type,1) is null;
